using System.Drawing;

namespace CamGh.Grasshopper;

/// <summary>Pixel-art 50x50 icons for the CamGh components (dark tile, white line work, lime accent).
/// Sources live in docs/images/icons; they are embedded here as PNG so no resource files are needed.</summary>
internal static class ComponentIcons
{
    public static readonly Bitmap Core = Load("");
    public static readonly Bitmap CutParameters = Load("");
    public static readonly Bitmap HorizontalRoughing = Load("");
    public static readonly Bitmap ParallelFinishing = Load("");
    public static readonly Bitmap MachineSetup = Load("");
    public static readonly Bitmap Stock = Load("");
    public static readonly Bitmap Tool = Load("");
    public static readonly Bitmap Analysis = Load("");
    public static readonly Bitmap MultiAxisRoughing = Load("");
    public static readonly Bitmap RegionFinishing = Load("");

    private static Bitmap Load(string base64)
    {
        using var ms = new System.IO.MemoryStream(Convert.FromBase64String(base64));
        using var img = new Bitmap(ms);
        return new Bitmap(img);   // detach from the stream
    }
}
